const axios = require('axios');
const fs = require('fs');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables
const envLines = envContent.split('\n').filter(line => line && !line.startsWith('#') && line.includes('='));
const envVars = {};

envLines.forEach(line => {
  const [key, value] = line.split('=');
  envVars[key.trim()] = value.trim();
});

// POST to the endpoint
axios.post('http://localhost:3003/api/doc-export', envVars, {
  headers: { 'Content-Type': 'application/json' }
})
.then(() => {
  console.log('Environment variables successfully exported');
})
.catch(error => {
  console.error('Failed to export environment variables:', error.response?.data || error.message);
  process.exit(1);
});

